from collections import deque
def comps(g,val):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==val and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<len(g) and 0<=nb<len(g[0]) and g[na][nb]==val and (na,nb) not in seen:
                                seen.add((na,nb)); q.append((na,nb))
                out.append(cells)
    return out
