# For each demo: list each non-bg color's input comps and output comps, normalized shape
for k in ['Demo pair %d'%i for i in range(1,8)]:
    i,o=G[k+' input'],G[k+' output']
    bg=max({v for row in i for v in row}, key=lambda v: sum(row.count(v) for row in i))
    print('===',k,'bg',bg,'in',len(i),'x',len(i[0]),'out',len(o),'x',len(o[0]))
    def comps_of(g,val):
        seen=set(); out=[]
        for r in range(len(g)):
            for c in range(len(g[0])):
                if g[r][c]==val and (r,c) not in seen:
                    q=deque([(r,c)]); seen.add((r,c)); cells=[]
                    while q:
                        a,b=q.popleft(); cells.append((a,b))
                        for da in(-1,0,1):
