    H,W=len(inp),len(inp[0])
    cs=comps(inp); bg=max({x for row in inp for x in row}, key=lambda v: sum(row.count(v) for row in inp))
    res=[[bg]*W for _ in range(H)]
    objs=[]
    for c,s in cs:
        # absorb single-cell comps touching bigger comp (already handled by 8-conn? no, separate comps per color)
        if len(s)==1:
            (r0,c0)=list(s)[0]
            absorbed=False
            for c2,s2 in cs:
                if c2!=c and len(s2)>1 and any(abs(r0-a)<=1 and abs(c0-b)<=1 for a,b in s2):
                    res[r0][c0]=c2; absorbed=True; break
            if not absorbed: res[r0][c0]=c
        else:
            objs.append((c,s))
    # slide each obj up-left until blocked by border or another obj cell
    placed=set()
    changed=True
    while changed:
        changed=False
        for idx,(c,s) in enumerate(objs):
            cand=s.copy()
            # try up
            ok=all(r-1>=0 and (r-1,c) not in placed and ((r-1,c) not in union(s) for c in [0]) for r,c in [])
            ok=True
            newcells={(r-1,c) for r,c in s}
            if all(r-1>=0 for r,c in s) and not any((r-1,c) in placed or ((r-1,c)!=(r,c) and (r,c) in s) for r,c in newcells-set(s)):
                pass
            ok=newcells<=set((r,c) for r in range(H) for c in range(W)) and not any(((r-1,c) in s) for r,c in newcells)
            if ok:
                s={(r-1,c) for r,c in s}; changed=True; continue
            # try left
            newcells={(r,c-1) for r,c in s}
            if all(c-1>=0 for r,c in s) and not any((r,c-1) in s for r,c in s) and not any((r,c-1) in placed for r,c in newcells):
                s={(r,c-1) for r,c in s}; changed=True; continue
    # paint
    for c,s in objs:
        for r,cc in s: res[r][cc]=c
    return res
